/* Semantic Versioning Reference */
// vue@"3.4.2" means:
//   MAJOR: 3 (breaking API changes from v2)
//   MINOR: 4 (new backward-compat features)
//   PATCH: 2 (bug fixes)

// Version ranges:
"vue": "^3.4.0"   // >=3.4.0 <4.0.0 (compatible)
"vue": "~3.4.0"   // >=3.4.0 <3.5.0 (patch only)
"vue": "3.4.0"    // Exactly 3.4.0 only
"vue": "*"        // Any version (dangerous!)
"vue": ">=3.0.0"  // Greater than or equal to 3.0.0

// Check for outdated packages:
// npm outdated
// Update safely:
// npm update (respects ranges)

// Root package.json for monorepo
{
  "name": "mission-monorepo",
  "private": true,
  "workspaces": [
    "apps/*",
    "packages/*"
  ]
}

// Structure:
// apps/web/         → Vue frontend
// apps/api/         → Express backend
// packages/shared/  → Shared types and utilities

// Install all workspace deps from root:
// npm install

// Run script in specific workspace:
// npm run dev --workspace=apps/web

// Install package in specific workspace:
// npm install axios --workspace=apps/api
